"use strict";
const crypto = require("crypto");
const { Buffer } = require("buffer");

// Configuration loaded from environment
const CONFIG = {
  HMAC_ALGORITHM: process.env.HMAC_ALGO || "sha256",
  ENCODING_MODE: process.env.ENCODING_MODE || "hex",
  KEY_DERIVATION_ROUNDS: parseInt(process.env.KDF_ROUNDS || "100000", 10),
  TOKEN_EXPIRY_MS: parseInt(process.env.TOKEN_EXPIRY || "3600000", 10),
  MASTER_KEY: process.env.MASTER_KEY || crypto.randomBytes(32).toString("hex")
};

class TokenAuthority {
  constructor(config) {
    this.algorithm = config.HMAC_ALGORITHM;
    this.encoding = config.ENCODING_MODE;
    this.rounds = config.KDF_ROUNDS;
    this.expiryMs = config.TOKEN_EXPIRY_MS;
    this.masterKey = this._deriveKey(config.MASTER_KEY);
  }

  _deriveKey(secret) {
    return crypto.pbkdf2Sync(
      secret,
      "token-authority-salt-v2",
      this.rounds,
      32,
      "sha512"
    );
  }

  _computeMAC(payload) {
    const hmac = crypto.createHmac(this.algorithm, this.masterKey);
    hmac.update(payload);
    return hmac.digest(this.encoding);
  }

  _normalizePayload(data) {
    // Normalize the payload to canonical form before signing
    const canonical = JSON.stringify(data, Object.keys(data).sort());
    // Apply encoding normalization based on configured mode
    const encoded = Buffer.from(canonical, "utf8");
    return encoded.toString(this.encoding);
  }

  issueToken(userId, roles, metadata = {}) {
    const now = Date.now();
    const payload = {
      sub: String(userId),
      roles: Array.isArray(roles) ? roles.sort() : [String(roles)],
      iat: now,
      exp: now + this.expiryMs,
      meta: metadata
    };

    const normalizedPayload = this._normalizePayload(payload);
    const mac = this._computeMAC(normalizedPayload);

    // Token format: base64url(payload).mac
    const payloadB64 = Buffer.from(JSON.stringify(payload)).toString("base64url");
    return `${payloadB64}.${mac}`;
  }

  verifyToken(token) {
    if (!token || typeof token !== "string") {
      return { valid: false, error: "Invalid token format" };
    }

    const parts = token.split(".");
    if (parts.length !== 2) {
      return { valid: false, error: "Malformed token structure" };
    }

    const [payloadB64, providedMAC] = parts;

    let payload;
    try {
      payload = JSON.parse(Buffer.from(payloadB64, "base64url").toString("utf8"));
    } catch (e) {
      return { valid: false, error: "Invalid payload encoding" };
    }

    // Check expiration
    if (!payload.exp || Date.now() > payload.exp) {
      return { valid: false, error: "Token expired" };
    }

    // Recompute MAC over the normalized payload
    const normalizedPayload = this._normalizePayload(payload);
    const expectedMAC = this._computeMAC(normalizedPayload);

    // Timing-safe comparison
    const macBuffer = Buffer.from(providedMAC, this.encoding);
    const expectedBuffer = Buffer.from(expectedMAC, this.encoding);

    if (macBuffer.length !== expectedBuffer.length) {
      return { valid: false, error: "MAC length mismatch" };
    }

    if (!crypto.timingSafeEqual(macBuffer, expectedBuffer)) {
      return { valid: false, error: "Invalid signature" };
    }

    return { valid: true, payload };
  }
}

class AuthMiddleware {
  constructor(tokenAuthority) {
    this.authority = tokenAuthority;
  }

  authenticate(req, res, next) {
    const authHeader = req.headers["authorization"];
    if (!authHeader || !authHeader.startsWith("Bearer ")) {
      return res.status(401).json({ error: "Missing authorization" });
    }

    const token = authHeader.slice(7);
    const result = this.authority.verifyToken(token);

    if (!result.valid) {
      return res.status(401).json({ error: result.error });
    }

    req.user = result.payload;
    next();
  }

  requireRole(role) {
    return (req, res, next) => {
      if (!req.user || !req.user.roles.includes(role)) {
        return res.status(403).json({ error: "Insufficient permissions" });
      }
      next();
    };
  }
}

// Factory function
function createAuthSystem(envConfig = CONFIG) {
  const authority = new TokenAuthority(envConfig);
  const middleware = new AuthMiddleware(authority);
  return { authority, middleware };
}

module.exports = { TokenAuthority, AuthMiddleware, createAuthSystem, CONFIG };
